perl -e '
use strict;
use warnings;

my $root = "/bench/repo";

# Persistent entity types (domain structs, not Find/Update/Delete helpers)
my @entities = qw(
  Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation MemoShare
  Reaction User UserIdentity UserSetting
);

# also consider Store itself? not an entity
# AuthenticationConfigState - maybe not persistent entity in same sense

my @files = split /\n/, `find "$root" -name "*.go" -type f ! -path "*/.git/*" ! -path "*/web/*" ! -path "*/proto/gen/*" ! -path "*/node_modules/*"`;

sub pkg_of {
  my ($path) = @_;
  $path =~ s{^\Q$root\E/}{};
  $path =~ s{/[^/]+$}{};
  return $path;
}

sub is_data_layer {
  my ($pkg) = @_;
  return 1 if $pkg eq "store";
  return 1 if $pkg =~ m{^store/};
  return 0;
}

my %pkg_mentions; # entity -> { pkg => count }
my %pkg_files;

for my $path (@files) {
  my $pkg = pkg_of($path);
  next if is_data_layer($pkg);
  open my $fh, "<", $path or next;
  local $/;
  my $src = <$fh>;
  close $fh;
  # skip if no store import
  next unless $src =~ /usememos\/memos\/store/;
  for my $ent (@entities) {
    my $n = () = $src =~ /\bstore\.$ent\b/g;
    if ($n > 0) {
      $pkg_mentions{$ent}{$pkg} += $n;
    }
  }
}

print "=== Entity ranked by distinct outside packages ===\n";
my @ranked = sort { scalar(keys %{$pkg_mentions{$b}}) <=> scalar(keys %{$pkg_mentions{$a}}) || $a cmp $b } @entities;
for my $ent (@ranked) {
  my $pkgs = $pkg_mentions{$ent} || {};
  my $np = scalar keys %$pkgs;
  my $refs = 0; $refs += $_ for values %$pkgs;
  print sprintf("%2d pkgs / %3d refs  %-20s  [%s]\n", $np, $refs, $ent, join(", ", sort keys %$pkgs));
}
'
